"""The sentinel: run what changed, once, and pick up the HUD queue."""
import json
from pathlib import Path

from scripts import watch
from woweconomy.intel import store
from woweconomy.pricing import deploy
from woweconomy.pricing.config import PricingConfig

#: enough for ``validate_dataset``: the deployment refuses anything else
VALID_DATASET = (
    "-- Generated by the DfA pricing engine.  Do not edit by hand.\n"
    "-- schema 2, engine 2.0.0, generated 1\n"
    "\n"
    "DFA_ESTIMATE = {\n"
    "\tversion = 2,\n"
    '\tengineVersion = "2.0.0",\n'
    "\tgeneratedAt = 1,\n"
    "\titemCount = 0,\n"
    "\trealmCount = 0,\n"
    "\tappearanceCount = 0,\n"
    "\ttotalObservations = 0,\n"
    "\tpriceCount = 0,\n"
    "\tindexedRealms = 0,\n"
    "}\n"
)


class FakeRunner:
    def __init__(self, payload=None):
        self.calls = []
        self.payload = payload or {}

    def __call__(self, argv, timeout=1800):
        self.calls.append(list(argv))
        return {"returncode": 0, "payload": self.payload, "stdout": "", "stderr": ""}


def make(tmp_path, runner=None, **overrides):
    db = tmp_path / "intel.sqlite"
    store.connect(db)
    dataset = tmp_path / "DFA_Estimate" / "Data" / deploy.DATA_FILE
    dataset.parent.mkdir(parents=True, exist_ok=True)
    dataset.write_text(VALID_DATASET, encoding="utf-8")
    addons = tmp_path / "AddOns"
    (addons / deploy.PACKAGE / "Data").mkdir(parents=True, exist_ok=True)
    cfg = watch.Config(
        offline=True, notify=False, state_path=tmp_path / "state.json",
        log_path=tmp_path / "watch.log", intel_db=str(db),
        tsm_db=str(tmp_path / "tsm.db"),
        addons_dir=str(addons), dataset_path=str(dataset),
        # the fixtures are written a moment ago; the production debounce
        # would (correctly) refuse to read them yet
        stable_s=0,
    )
    for key, value in overrides.items():
        setattr(cfg, key, value)
    return watch.Watch(cfg, runner=runner or FakeRunner())


def export_with_actions(tmp_path, actions):
    lines = "\n".join(json.dumps(action) for action in actions)
    path = tmp_path / "DFA_AuctionIntelligence.lua"
    path.write_text(
        "DFA_AUCTION_INTELLIGENCE_EXPORT = {\n"
        f"\t[\"actions_jsonl\"] = {json.dumps(lines)},\n"
        "}\n", encoding="utf-8")
    return path


def test_a_changed_input_runs_its_task_then_the_export():
    tasks = watch.plan(10_000, {}, {"addon": True},
                       watch.Config(offline=True))
    names = [task.name for task in tasks]

    assert names == ["addon", "train", "sentinel", "export"]
    assert "SavedVariables" in tasks[0].reason


def test_a_recent_fit_and_a_recent_export_do_not_run_again():
    now = 100_000
    state = {"last": {"train": now - 3600, "sentinel": now - 3600,
                      "export": now - 3600, "ah": now - 60}}
    tasks = watch.plan(now, state, {"addon": True},
                       watch.Config(offline=True))

    assert [task.name for task in tasks] == ["addon"]


def test_the_blizzard_job_is_hourly_and_skipped_offline():
    now = 100_000
    due = watch.plan(now, {"last": {"train": now, "export": now}},
                     {}, watch.Config(realms=["Dragonmaw"]))
    offline = watch.plan(now, {"last": {"train": now, "export": now}},
                         {}, watch.Config(realms=["Dragonmaw"], offline=True))

    assert "ah" in [task.name for task in due]
    assert "ah" not in [task.name for task in offline]


def test_the_hourly_ah_job_runs_without_an_explicit_realm_list():
    now = 100_000
    state = {"last": {"train": now, "sentinel": now, "export": now,
                      "ah": now - 3601}}

    tasks = watch.plan(now, state, {}, watch.Config(realms=[]))

    # the daemon is started without --realms; that must not stop the scan
    assert [task.name for task in tasks] == ["ah"]


def test_realms_come_from_the_data_with_no_cap_and_no_fixed_fallback(tmp_path):
    watch_ = make(tmp_path)
    con = watch_.con()
    realms = ["Silvermoon", "Twisting Nether", "Kazzak", "Draenor",
              "Antonidas", "Auchindoun"]
    for index, realm in enumerate(realms):
        con.execute(
            "INSERT INTO inventory_snapshot (snapshot_id, captured_at, realm)"
            " VALUES (?,?,?)", (f"s{index}", index, realm))
    con.commit()

    assert watch_.realms() == sorted(realms, key=str.lower)


def test_no_discovered_realm_is_an_empty_list_not_a_guess(tmp_path):
    watch_ = make(tmp_path)

    assert watch_.realms() == []
    # and the task says so instead of scanning a market the player is not on
    assert watch_.task_ah(now=1_000)["skipped"] == "no realm discovered"


def test_a_signature_change_is_detected_once(tmp_path):
    path = tmp_path / "input.lua"
    path.write_text("a", encoding="utf-8")
    state = {}
    sources = {"addon": str(path)}

    first = watch.changed_sources(state, sources)
    watch.mark_sources(state, sources)
    second = watch.changed_sources(state, sources)
    path.write_text("ab", encoding="utf-8")
    third = watch.changed_sources(state, sources)

    assert first == {"addon": True}
    assert second == {"addon": False}
    assert third == {"addon": True}


def test_a_file_still_being_written_is_read_on_a_later_tick(tmp_path):
    path = tmp_path / "input.lua"
    path.write_text("a", encoding="utf-8")
    state = {}
    sources = {"addon": str(path)}
    now = int(path.stat().st_mtime)

    too_fresh = watch.changed_sources(state, sources, now=now, stable_s=30)
    settling = watch.settling_sources(state, sources, now=now, stable_s=30)
    watch.mark_sources(state, sources, skip=settling)
    later = watch.changed_sources(state, sources, now=now + 60, stable_s=30)

    assert too_fresh == {"addon": False}
    assert settling == {"addon"}
    # the debounce defers the read; it must not record the file as seen
    assert later == {"addon": True}


def test_a_tick_imports_trains_exports_and_remembers_the_signature(tmp_path):
    runner = FakeRunner()
    watch_ = make(tmp_path, runner)
    addon = export_with_actions(tmp_path, [])
    watch_.sources_fn = lambda: {"addon": str(addon), "journal": None,
                                 "tsm": None, "csv": None}

    first = watch_.tick(now=1_000)
    assert [task["task"] for task in first["tasks"]] == [
        "addon", "train", "sentinel", "export"]
    assert [call[1] for call in runner.calls] == [
        "scripts/intel.py", "scripts/intel.py", "scripts/dfa_ml.py",
        "scripts/dfa_pricing_export.py"]

    second = watch_.tick(now=1_100)
    assert second["tasks"] == []
    assert len(runner.calls) == 4


def test_a_hud_press_is_imported_once_and_keeps_its_result(tmp_path):
    runner = FakeRunner()
    watch_ = make(tmp_path, runner)
    addon = export_with_actions(tmp_path, [
        {"name": "undercut", "at": 900, "ok": True, "detail": "scan started"},
        {"name": "mail", "at": 901, "ok": False, "detail": "no inbox"},
    ])
    watch_.cfg.addon_path = str(addon)
    watch_.sources_fn = lambda: {"addon": str(addon)}

    first = watch_.task_addon(now=1_000)
    second = watch_.task_addon(now=1_100)

    assert [action["name"] for action in first["actions"]] == ["undercut", "mail"]
    assert first["actions"][1]["ok"] is False
    assert "actions" not in second
    assert len(watch_.state["actions_seen"]) == 2


def test_a_second_daemon_is_refused_the_lock(tmp_path):
    lock = tmp_path / "watch.lock"
    first = watch.acquire_lock(lock)

    assert first is not None
    try:
        assert lock.read_text(encoding="utf-8").strip().isdigit()
        assert watch.acquire_lock(lock) is None
    finally:
        first.close()

    # the OS drops the lock with the process, so a crash leaves nothing stale
    again = watch.acquire_lock(lock)
    assert again is not None
    again.close()


def test_a_tsm_write_inside_the_gap_queues_the_export_instead_of_running_it():
    now = 100_000
    state = {"last": {"train": now, "sentinel": now, "export": now - 60}}

    tasks = watch.plan(now, state, {"tsm": True},
                       watch.Config(offline=True, export_min_gap_min=30))

    assert [task.name for task in tasks] == ["sync"]
    # the change is remembered, not dropped
    assert state["export_pending"] is True


def test_a_queued_export_runs_after_the_gap_with_no_new_change():
    now = 100_000
    state = {"last": {"train": now - 40 * 60, "sentinel": now - 60,
                      "export": now - 31 * 60},
             "export_pending": True}

    tasks = watch.plan(now, state, {}, watch.Config(offline=True))

    assert [task.name for task in tasks] == ["export"]
    assert "cooling" in tasks[0].reason


def test_a_queued_export_waits_while_the_gap_is_still_open():
    now = 100_000
    state = {"last": {"train": now, "sentinel": now, "export": now - 60},
             "export_pending": True}

    assert watch.plan(now, state, {}, watch.Config(offline=True)) == []


def test_a_good_export_deploys_the_dataset_to_both_copies(tmp_path):
    watch_ = make(tmp_path)

    detail = watch_.task_export(now=1_000)

    assert detail["deploy"]["ok"] is True
    canonical = Path(watch_.cfg.dataset_path)
    installed = (Path(watch_.cfg.addons_dir) / deploy.PACKAGE / "Data"
                 / deploy.DATA_FILE)
    assert installed.read_bytes() == canonical.read_bytes()
    report = deploy.verify(PricingConfig(dataset_path=canonical,
                                         addons_dir=Path(watch_.cfg.addons_dir)))
    assert report["in_sync"] is True


def test_a_dataset_written_outside_the_daemon_is_scheduled_for_deployment():
    now = 100_000
    state = {"last": {"train": now, "sentinel": now, "export": now}}

    tasks = watch.plan(now, state, {"dataset": True}, watch.Config(offline=True))

    assert [task.name for task in tasks] == ["deploy"]


def test_a_manual_export_reaches_the_game_on_the_next_tick(tmp_path):
    watch_ = make(tmp_path)
    canonical = Path(watch_.cfg.dataset_path)
    installed = (Path(watch_.cfg.addons_dir) / deploy.PACKAGE / "Data"
                 / deploy.DATA_FILE)
    # a manual `dfa_pricing_export.py` run, outside the daemon
    canonical.write_text(VALID_DATASET.replace("generatedAt = 1,",
                                               "generatedAt = 7,"),
                         encoding="utf-8")
    watch_.state["last"] = {"train": 1_000, "sentinel": 1_000, "export": 1_000}
    watch_.sources_fn = lambda: {"dataset": str(canonical)}

    result = watch_.tick(now=1_100)

    assert [task["task"] for task in result["tasks"]] == ["deploy"]
    assert result["tasks"][0]["detail"]["deploy"]["ok"] is True
    assert installed.read_bytes() == canonical.read_bytes()


def test_a_deploy_superseded_by_a_new_export_is_queued(monkeypatch, tmp_path):
    watch_ = make(tmp_path)

    def superseded(config, **kwargs):
        return deploy.DeployResult(ok=False, source=str(config.dataset_path),
                                   superseded=True)

    monkeypatch.setattr(deploy, "deploy", superseded)

    detail = watch_.task_export(now=1_000)

    assert detail["deploy"]["superseded"] is True
    # the newer export must not be lost: the next tick ships it
    assert watch_.state["export_pending"] is True


def test_a_failed_export_keeps_the_change_queued(tmp_path):
    def failing(argv, timeout=1800):
        return {"returncode": 1, "stdout": "", "stderr": "boom", "payload": None}

    watch_ = make(tmp_path, failing)

    assert watch_.task_export(now=1_000)["export"] == 1
    assert watch_.state["export_pending"] is True


def test_a_good_export_clears_the_queue(tmp_path):
    watch_ = make(tmp_path)
    watch_.state["export_pending"] = True

    watch_.task_export(now=1_000)

    assert "export_pending" not in watch_.state


def test_dry_run_runs_nothing_and_writes_nothing(tmp_path):
    runner = watch.Runner(dry_run=True)
    watch_ = make(tmp_path, runner)
    addon = export_with_actions(tmp_path, [])
    watch_.cfg.dry_run = True
    watch_.sources_fn = lambda: {"addon": str(addon)}

    result = watch_.tick(now=1_000)

    assert result["tasks"]
    assert not (tmp_path / "state.json").exists()
    assert not watch_.state.get("last")
